        "【第 3 步：階梯推導 · 逐步拆解運算／推理過程】1. 先針對題幹核心問題「明末天主教耶穌會傳教士利瑪竇來到中國傳教，為了爭取朝廷與士大夫信任，主要採取何種傳教策略？」進行分析：利瑪竇穿儒服、讀儒書，並帶來西洋天文鐘、三稜鏡、《幾何原本》與《坤輿萬國全圖》，開創「學術傳教」路線。\n2. 核對各選項與課綱判準：選項 (B) 準確指出「融入儒家文化並介紹西方天文數學與地圖科技」之結論，並完整扣合「明清市場與對外交流」與「出處」的成立條件。\n3. 驗證遷移情境：市場發展不代表自給活動立刻消失；兩者可在同一地區並存，確認選項 (B) 推論嚴密無誤。",
