        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「季風亞洲與世界文明搖籃」核心知識點：\n1. 氣候自然帶對稱分布：赤道為熱帶雨林，向南北兩側依序對稱過渡為熱帶莽原、熱帶沙漠與地中海氣候（實證檢核：地形以古老結晶岩高原為主，海岸線平直少天然良港，河川多急湍瀑布不利內河航運）。\n2. 熱帶莽原乾濕分明：夏受赤道低壓壟罩為雨季，草木繁茂；冬受副熱帶高壓控制為乾季，草木枯黃（實證檢核：野生動物隨雨帶季節性長途遷徙；游牧與傳統農業依乾濕季輪替）。\n3. 關鍵推理原則：東亞、南亞與東南亞受海陸比熱差異影響形成顯著的季風氣候（夏季吹向大陸帶來豐沛暖濕水氣，冬季吹向海洋寒冷乾燥）。季風亞洲雨熱同期的氣候特點極度有利於水稻種植，造就精耕細作的集約農業與世界最高人口密度聚居區。印度河、恆河、黃河與長江流域孕育了深厚悠久的人類古典文明。",
