        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「少年法律保護與權益維護」核心知識點：\n1. 少年法年齡界定：少年：12 歲以上未滿 18 歲；兒童：未滿 12 歲（實證檢核：未滿 12 歲兒童觸犯刑責不移送少年法院，回歸教育與社政體系（全面除罪化））。\n2. 少年保護事件處理：以「保護優先」與「教育矯治」為核心，由少年法院（庭）調查審理（實證檢核：保護處分種類：訓誡、假日生活輔導、保護管束、安置輔導、感化教育）。\n3. 關鍵推理原則：法律考量少年（12 歲以上未滿 18 歲）身心發展尚未成熟，以保護優先而非純懲罰。《少年事件處理法》分為少年保護事件（少年偏差行為或觸法情節輕微，施以訓誡、假日生活輔導、保護管束、感化教育）與少年刑事案件（觸犯重罪者始適用刑法）。《兒童及少年福利與權益保障法》保障兒少免於受虐、剝削與身心侵害。",
