        "【第 2 步：破題關鍵 · 課綱概念與核心公式】依據 108 課綱「二次大戰後冷戰對峙與全球解殖潮」核心知識點：\n1. 美蘇冷戰對峙與亞非解殖：美國資本陣營（馬歇爾計畫、北約）vs 蘇聯共產陣營（華沙公約）；1991 蘇聯解體冷戰結束（實證檢核：1950 韓戰爆發後美國派第七艦隊協防臺海；亞非新興獨立國形成不結盟運動（第三世界））。\n2. 出處：誰在何時、何地、為誰留下紀錄？（實證檢核：當時人的日記能呈現經驗，但不代表所有人的觀點）。\n3. 關鍵推理原則：二戰後以美國為首的資本主義民主陣營（成立北約組織 NATO）與以蘇聯為首的共產極權陣營（華沙公約組織）形成「冷戰」長期對峙。美蘇避免全面核戰，透過代理人戰爭（如韓戰、越戰）、軍備競賽與太空競賽爭霸；歐洲分裂（柏林圍牆）。亞洲與非洲在戰後掀起大規模「去殖民化」民族獨立浪潮，印度（甘地非暴力不合作運動後獨立）、東南亞與非洲諸國相繼脫離歐美殖民統治。1991 年蘇聯解體標誌冷戰結束。",
