      "stem": "閱讀以下「地方自治、社區參與與地方創生」之跨情境探究案例與對照資料：\n【情境案例與數據觀察】社區想改善公園照明，如何把抱怨轉成可處理的公共提案？\n【延伸實證紀錄】某縣市政府編列預算擬興建垃圾焚化廠，縣議會有權刪減或否決該筆預算；當地社區居民若有疑慮，亦可依法連署提出地方性公民投票，決定公共設施設置與否。\n根據 108 課綱「公民與社會」核心知識點與判準，針對上述情境及「依據地方制度法規定，下列地方行政區中，哪一個層級的首長是由市長直接派任（官派），而非由市民直接投票選舉產生？」之綜合判斷，下列敘述何者最為正確？",
