      "stem": "閱讀以下「中央政府體制與五院職權分工制衡」之跨情境探究案例與對照資料：\n【情境案例與數據觀察】看到行政機關提出政策、立法機關審議法律與預算，能否說行政部門可以自行決定所有法律？\n【延伸實證紀錄】行政院若認為立法院通過的法律案或預算案窒礙難行，經總統核可後可移請立法院「覆議」；若立法院全體立法委員二分之一以上決議維持原案，行政院長即應接受該決議。\n根據 108 課綱「公民與社會」核心知識點與判準，針對上述情境及「當立法院通過某項重大法案，行政院認為其執行有窒礙難行之處時，依法可透過何種憲政機制尋求救濟與制衡？」之綜合判斷，下列敘述何者最為正確？",
